   150→// HasOtherActiveSessionsWithCheckpoints checks if there are other active sessions
   151→// from the SAME worktree (different from currentSessionID) that have created checkpoints
   152→// on the SAME base commit (current HEAD). This is used to detect concurrent sessions
   153→// in different terminals but same directory.
   154→// Returns the first found session with CheckpointCount > 0, or nil if none found.
   155→func (s *ManualCommitStrategy) HasOtherActiveSessionsWithCheckpoints(currentSessionID string) (*SessionState, error) {
   156→	currentWorktree, err := GetWorktreePath()
   157→	if err != nil {
   158→		return nil, err
   159→	}
   160→
   161→	// Get current HEAD to compare with session base commits
   162→	repo, err := OpenRepository()
   163→	if err != nil {
   164→		return nil, err
   165→	}
   166→	head, err := repo.Head()
   167→	if err != nil {
   168→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
   169→	}
   170→	currentHead := head.Hash().String()
   171→
   172→	allStates, err := s.listAllSessionStates()
   173→	if err != nil {
   174→		return nil, err
   175→	}
   176→
   177→	for _, state := range allStates {
   178→		// Only consider sessions from the same worktree with checkpoints
   179→		// AND based on the same commit (current HEAD)
   180→		// Sessions from different base commits are independent and shouldn't trigger warning
   181→		if state.SessionID != currentSessionID &&
   182→			state.WorktreePath == currentWorktree &&
   183→			state.CheckpointCount > 0 &&
   184→			state.BaseCommit == currentHead {
   185→			return state, nil
   186→		}
   187→	}
   188→	return nil, nil //nolint:nilnil // nil,nil indicates no other session found (expected case)
   189→}
